    const depth={},tone={},hidden=new Set(),rootOf={};
    const walk=(n,d,t,hid,rt,bi)=>{depth[n.id]=d;rootOf[n.id]=rt;const own=n.color!==null&&n.color!==undefined?n.color:(d===0?0:t);tone[n.id]=own;if(hid)hidden.add(n.id);(kids.get(n.id)||[]).forEach((k,i)=>walk(k,d+1,d===0?(i%5)+1:own,hid||n.collapsed,rt,i));};
