    let x0=1e9,y0=1e9,x1=-1e9,y1=-1e9;nodes.forEach(n=>{const p=MM.disp[n.id]||{x:n.x,y:n.y},s=MM.size[n.id]||mmEst(n);x0=Math.min(x0,p.x-s.w/2);x1=Math.max(x1,p.x+s.w/2);y0=Math.min(y0,p.y-s.h/2);y1=Math.max(y1,p.y+s.h/2);});
