  // Now Playing: foobar2000 metadata is supplied by the optional local StudyOS bridge.
  const np = {trackKey:'',track:null,lyrics:[],synced:false,lastLookup:0,poll:null,position:0,duration:0,open:false};
  const NP_BRIDGE='http://127.0.0.1:8765';
  const npEls={trigger:$('#nowPlayingTrigger'),popover:$('#nowPlayingPopover'),miniArt:$('#npMiniArt'),miniTitle:$('#npMiniTitle'),miniArtist:$('#npMiniArtist'),miniLyric:$('#npMiniLyric'),equalizer:$('#npEqualizer'),connection:$('#npConnection'),largeArt:$('#npLargeArt'),title:$('#npTrackTitle'),artist:$('#npTrackArtist'),album:$('#npTrackAlbum'),status:$('#npLyricsStatus'),lyrics:$('#npLyrics'),current:$('#npCurrentTime'),duration:$('#npDuration'),fill:$('#npProgressFill')};
  const npTime=v=>{v=Math.max(0,Math.floor(Number(v)||0));return `${Math.floor(v/60)}:${String(v%60).padStart(2,'0')}`;};
  function npSetArt(url){[npEls.miniArt,npEls.largeArt].forEach(el=>{if(!el)return;el.style.backgroundImage=url?`url("${url.replace(/"/g,'%22')}")`:'';el.textContent=url?'':'♫';});}
  function npSetConnection(ok,msg){if(!npEls.connection)return;npEls.connection.textContent=msg|| (ok?'CONNECTED':'OFFLINE');npEls.connection.classList.toggle('connected',!!ok);}
  function npSetLyricsMessage(msg){if(npEls.status)npEls.status.textContent=msg;if(npEls.lyrics)npEls.lyrics.innerHTML=`<p class="np-lyrics-empty">${esc(msg)}</p>`;if(npEls.miniLyric)npEls.miniLyric.textContent=msg;np.lyrics=[];np.synced=false;}
  function npParseLrc(raw){return String(raw||'').split(/\r?\n/).flatMap(line=>{const matches=[...line.matchAll(/\[(\d{1,2}):(\d{2})(?:\.(\d{1,3}))?\]/g)];const text=line.replace(/\[[^\]]+\]/g,'').trim();return matches.map(m=>({time:Number(m[1])*60+Number(m[2])+Number(`0.${m[3]||'0'}`),text}));}).sort((a,b)=>a.time-b.time);}
  async function npLookupLyrics(track){const params=new URLSearchParams({track_name:track.title,artist_name:track.artist});if(track.album)params.set('album_name',track.album);if(track.duration>0)params.set('duration',String(Math.round(track.duration)));try{let r=await fetch(`https://lrclib.net/api/get?${params}`,{headers:{'Accept':'application/json'}});let d;if(r.ok){d=await r.json();}else if(r.status===404){const search=new URLSearchParams({track_name:track.title,artist_name:track.artist});r=await fetch(`https://lrclib.net/api/search?${search}`,{headers:{'Accept':'application/json'}});if(!r.ok)throw new Error('No lyrics found');const matches=await r.json();d=matches.find(x=>x.syncedLyrics)||matches[0];if(!d)throw new Error('No lyrics found');}else throw new Error('Lyrics service unavailable');if(d.syncedLyrics){np.lyrics=npParseLrc(d.syncedLyrics);np.synced=np.lyrics.length>0;}else if(d.plainLyrics){np.lyrics=String(d.plainLyrics).split(/\r?\n/).map(text=>({time:null,text}));np.synced=false;}else throw new Error('No lyrics found');npRenderLyrics();npEls.status.textContent=np.synced?'Synced lyrics · LRCLIB':'Plain lyrics · LRCLIB';}catch(e){npSetLyricsMessage(e.message==='Failed to fetch'?'Could not reach LRCLIB. Check your connection.':e.message);}}
  function npRenderLyrics(){if(!npEls.lyrics)return;if(!np.lyrics.length){npSetLyricsMessage('No lyrics available for this track.');return;}npEls.lyrics.innerHTML=np.lyrics.map((line,i)=>`<p class="np-lyrics-line" data-np-line="${i}">${esc(line.text||'♪')}</p>`).join('');npUpdateLyricsPosition(true);}
  async function npLookupArtwork(track){try{const q=new URLSearchParams({term:`${track.artist} ${track.title}`,entity:'song',limit:'1'});const r=await fetch(`https://itunes.apple.com/search?${q}`);if(!r.ok)return '';const d=await r.json();const item=d.results?.[0];return item?.artworkUrl100?.replace('100x100bb','600x600bb')||'';}catch{return '';}}
  function npUpdateLyricsPosition(force=false){if(!np.synced||!np.lyrics.length||!npEls.lyrics)return;let active=-1;for(let i=0;i<np.lyrics.length;i++){if(np.lyrics[i].time<=np.position)active=i;else break;}$$('[data-np-line]',npEls.lyrics).forEach((el,i)=>el.classList.toggle('active',i===active));const line=active>=0?np.lyrics[active]:null;if(npEls.miniLyric)npEls.miniLyric.textContent=line?.text||'♪';if(line){const el=$(`[data-np-line="${active}"]`,npEls.lyrics);if(el){const target=el.offsetTop-(npEls.lyrics.clientHeight-el.offsetHeight)/2;const delta=Math.abs(npEls.lyrics.scrollTop-target);if(force||delta>npEls.lyrics.clientHeight*.22)npEls.lyrics.scrollTo({top:Math.max(0,target),behavior:reduceMotion()?'auto':'smooth'});}}}
  function npRenderTrack(t){const title=t.title||'Unknown title',artist=t.artist||'Unknown artist',album=t.album||'';npEls.miniTitle.textContent=title;npEls.miniArtist.textContent=artist;npEls.title.textContent=title;npEls.artist.textContent=artist;npEls.album.textContent=album;npEls.equalizer.classList.toggle('is-playing',t.playbackState==='playing');npEls.trigger?.setAttribute('aria-label',`Now playing ${title} by ${artist}`);}
  async function npPoll(){try{const r=await fetch(`${NP_BRIDGE}/now-playing`,{cache:'no-store'});if(!r.ok)throw new Error('Bridge unavailable');const d=await r.json();if(!d.connected){npSetConnection(false,'FOOBAR2000 OFF');npEls.miniTitle.textContent='Now Playing';npEls.miniArtist.textContent='Open foobar2000';npEls.title.textContent='Nothing playing';npEls.artist.textContent='Open foobar2000 to begin';npEls.album.textContent='';npSetArt('');npEls.equalizer.classList.remove('is-playing');np.position=0;np.duration=0;npEls.fill.style.width='0%';npEls.current.textContent='0:00';npEls.duration.textContent='0:00';np.trackKey='';npSetLyricsMessage('Waiting for foobar2000 playback.');return;}npSetConnection(true,'FOOBAR2000 CONNECTED');const t=d.track||{};t.playbackState=d.playbackState||'stopped';t.position=Number(d.position)||0;t.duration=Number(d.duration)||0;np.position=t.position;np.duration=t.duration;np.track=t;npRenderTrack(t);npEls.current.textContent=npTime(t.position);npEls.duration.textContent=npTime(t.duration);npEls.fill.style.width=`${t.duration?Math.min(100,t.position/t.duration*100):0}%`;npUpdateLyricsPosition();const key=[t.title,t.artist,t.album].join('|');if(key!==np.trackKey){np.trackKey=key;if(d.artwork)npSetArt(`data:${d.artworkMime||'image/jpeg'};base64,${d.artwork}`);else npSetArt('');np.lyrics=[];np.synced=false;npSetLyricsMessage('Finding lyrics…');npLookupLyrics(t);const art=await npLookupArtwork(t);if(art)npSetArt(art);}}catch{np.trackKey='';npSetConnection(false,'BRIDGE OFFLINE');npEls.miniTitle.textContent='Now Playing';npEls.miniArtist.textContent='Start StudyOS bridge';npEls.equalizer.classList.remove('is-playing');if(!np.trackKey)npSetLyricsMessage('Start the StudyOS bridge and install the foobar2000 Beefweb component to connect.');}}
  async function npControl(action){try{const r=await fetch(`${NP_BRIDGE}/control/${action}`,{method:'POST'});if(!r.ok)throw new Error();setTimeout(npPoll,180);}catch{npSetConnection(false,'BRIDGE OFFLINE');toast('Could not control foobar2000. Check the local bridge.');}}
  if(npEls.trigger){npEls.trigger.addEventListener('click',()=>{np.open=!np.open;npEls.popover.hidden=!np.open;npEls.trigger.setAttribute('aria-expanded',String(np.open));if(np.open)npPoll();});document.addEventListener('click',e=>{if(np.open&&!$('#nowPlayingWrap')?.contains(e.target)){np.open=false;npEls.popover.hidden=true;npEls.trigger.setAttribute('aria-expanded','false');}});$('#nowPlayingPopover')?.addEventListener('click',e=>{const b=e.target.closest('[data-np-control]');if(b)npControl(b.dataset.npControl);});$('#npRetry')?.addEventListener('click',npPoll);np.poll=setInterval(npPoll,1800);npPoll();}
